/* Retire old Chirpy offline cache and unregister the service worker. */
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',e=>{e.waitUntil((async()=>{try{for(const key of await caches.keys())await caches.delete(key)}catch(_){}try{await self.registration.unregister()}catch(_){}try{for(const client of await self.clients.matchAll({type:'window',includeUncontrolled:true}))client.navigate(client.url).catch(()=>{})}catch(_){}})())});
